SELECT 2886 AS model_id, '38841' AS product_source_id, UNHEX('e79c9fe688912051336920283547e7898829') AS node_name, 11499 AS template_id, 'pjt_fdeb9fc4c79f7c53b3cd37f337892330' AS template_key
