SELECT 3641 AS model_id, '21632' AS product_source_id, UNHEX('e88194e683b32053363836') AS node_name, 28 AS template_id, 'pjt_e673f5f1daacbf65b9b168cb454f5356' AS template_key
UNION ALL
SELECT 3642 AS model_id, '21631' AS product_source_id, UNHEX('e88194e683b3204d41313638') AS node_name, 28 AS template_id, 'pjt_e673f5f1daacbf65b9b168cb454f5356' AS template_key
UNION ALL
SELECT 3643 AS model_id, '21630' AS product_source_id, UNHEX('e88194e683b32053363936') AS node_name, 28 AS template_id, 'pjt_e673f5f1daacbf65b9b168cb454f5356' AS template_key
UNION ALL
SELECT 3644 AS model_id, '21629' AS product_source_id, UNHEX('e88194e683b32041353330') AS node_name, 28 AS template_id, 'pjt_e673f5f1daacbf65b9b168cb454f5356' AS template_key
UNION ALL
SELECT 3645 AS model_id, '21628' AS product_source_id, UNHEX('e88194e683b3204d41333039') AS node_name, 28 AS template_id, 'pjt_e673f5f1daacbf65b9b168cb454f5356' AS template_key
) verified
JOIN saas_recycle_device_model_dict m
  ON m.id=verified.model_id AND m.site_id=0 AND m.node_type='model'
 AND m.source='recycle_spider' AND m.status=1
 AND BINARY m.product_source_id=BINARY verified.product_source_id
 AND BINARY m.node_name=verified.node_name
JOIN saas_recycle_check_template t
  ON t.id=verified.template_id AND t.site_id=0 AND t.status=1
 AND BINARY t.template_key=BINARY verified.template_key
LEFT JOIN saas_recycle_template_binding existing
  ON existing.site_id=0 AND existing.target_type='model_dict'
 AND existing.target_id=m.id AND existing.scene_key='manual_device_label'
WHERE existing.id IS NULL
 AND (EXISTS (SELECT 1 FROM saas_recycle_check_field f
              WHERE f.site_id=0 AND f.template_id=t.id)
      OR CASE WHEN JSON_VALID(t.schema_json)
         THEN COALESCE(JSON_LENGTH(JSON_EXTRACT(t.schema_json,'$.groups[*].fields[*]')),0)
         ELSE 0 END > 0);

