SELECT 5137 AS model_id, '30855' AS product_source_id, UNHEX('e8b0b7e6ad8c20506978656c203341') AS node_name, 1507 AS template_id, 'pjt_fa8cc6d8c4d7278f0585b490ad8f20c3' AS template_key
) verified
JOIN saas_recycle_device_model_dict m
  ON m.id=verified.model_id AND m.site_id=0 AND m.node_type='model'
 AND m.source='recycle_spider' AND m.status=1
 AND BINARY m.product_source_id=BINARY verified.product_source_id
 AND BINARY m.node_name=verified.node_name
JOIN saas_recycle_check_template t
  ON t.id=verified.template_id AND t.site_id=0 AND t.status=1
 AND BINARY t.template_key=BINARY verified.template_key
LEFT JOIN saas_recycle_template_binding existing
  ON existing.site_id=0 AND existing.target_type='model_dict'
 AND existing.target_id=m.id AND existing.scene_key='manual_device_label'
WHERE existing.id IS NULL
 AND (EXISTS (SELECT 1 FROM saas_recycle_check_field f
              WHERE f.site_id=0 AND f.template_id=t.id)
      OR CASE WHEN JSON_VALID(t.schema_json)
         THEN COALESCE(JSON_LENGTH(JSON_EXTRACT(t.schema_json,'$.groups[*].fields[*]')),0)
         ELSE 0 END > 0);

