SELECT 6341 AS model_id, '139942' AS product_source_id, UNHEX('e9a39ee588a9e6b5a6205336323031') AS node_name, 14495 AS template_id, 'pjt_5a78acbc072358aeb64c20ea950be35e' AS template_key
