SELECT 7893 AS model_id, '184924' AS product_source_id, UNHEX('e88194e683b320594f474120426f6f6b20396920204149e58583e590af203133e5afb8') AS node_name, 12698 AS template_id, 'pjt_afee7dd3762485486184210f96e2cbc4' AS template_key
