SELECT 13048 AS model_id, '37039' AS product_source_id, UNHEX('e7b4a2e5b0bc2056474e20e7b3bbe58897203131e5afb8') AS node_name, 11983 AS template_id, 'pjt_5da8bceb79bdd1465c52b70fc246728f' AS template_key
