SELECT 14326 AS model_id, '19869' AS product_source_id, UNHEX('e6b885e58d8ee5908ce696b9205334334220e7b3bbe58897') AS node_name, 10961 AS template_id, 'pjt_7a75e637991307cfd0c50376778b40ea' AS template_key
