SELECT 20616 AS model_id, '161410' AS product_source_id, UNHEX('e88bb9e69e9c20416972506f647320342028e4b88de694afe68c81e4b8bbe58aa8e9998de599aa29') AS node_name, 13143 AS template_id, 'pjt_26312ec123a86bfb14fce9de1b81cc9e' AS template_key
