SELECT 21050 AS model_id, '30435' AS product_source_id, UNHEX('e6a3aee6b5b7e5a19ee5b094204844342e3430425420574952454c455353') AS node_name, 9 AS template_id, 'pjt_17d123d5f87b61bc0cdd418978b838ed' AS template_key
