SELECT 21886 AS model_id, '129263' AS product_source_id, UNHEX('e6bcabe6ada5e880852057323030425420e9a288e68c82e78988') AS node_name, 11108 AS template_id, 'pjt_d737cdc37255dcc27a05c6bda3a9fd65' AS template_key
