SELECT 24247 AS model_id, '220686' AS product_source_id, UNHEX('e79c9fe6889120427564732041697220372050726f') AS node_name, 11403 AS template_id, 'pjt_46e9bc5bafdd46b7b179ba2a264f58ed' AS template_key
