SELECT 30843 AS model_id, '257372' AS product_source_id, UNHEX('e99fb3e4b990e9aa91e5a3ab205433') AS node_name, 593 AS template_id, 'pjt_785c5e562f83501b88a26613ce8d96b7' AS template_key
