UNION ALL
SELECT 38928 AS model_id, '15824' AS product_source_id, UNHEX('e6b5b7e5b094533636') AS node_name, 538 AS template_id, 'pjt_e779900c5d4a0c7daef1606483232b4d' AS template_key
