SELECT 39343 AS model_id, '37167' AS product_source_id, UNHEX('e7b4a2e5b0bc204856522d5a3143') AS node_name, 637 AS template_id, 'pjt_018a72fb8788fa6cf5bf817a4b70a7b2' AS template_key
