UNION ALL
SELECT 40423 AS model_id, '161369' AS product_source_id, UNHEX('e7a59ee7899b204450363030494949') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
