SELECT 41364 AS model_id, '131904' AS product_source_id, UNHEX('e9ad85e6978f2050414e44414552205041534120e9998de599aae880b3e69cba2053583132') AS node_name, 7 AS template_id, 'pjt_fc41f297211b2c5f8ed84544a85a998a' AS template_key
