SELECT 41784 AS model_id, '138683' AS product_source_id, UNHEX('e6bcabe6ada5e8808520e5a3b0e8bf88583220506c7573') AS node_name, 1916 AS template_id, 'pjt_c7f6f713c3d6fbaefc14dc0f0823f6c4' AS template_key
