SELECT 42302 AS model_id, '261450' AS product_source_id, UNHEX('e697b6e7a9bae5a3b62057342050726f') AS node_name, 680 AS template_id, 'pjt_1fecaa12f576574318f58ca23c98480c' AS template_key
