SELECT 42900 AS model_id, '262959' AS product_source_id, UNHEX('4a4c61622045706963204169722053706f727420414e43') AS node_name, 595 AS template_id, 'pjt_c0cff7af87f317e7c14de8254c9d2042' AS template_key
