SELECT 44655 AS model_id, '60158' AS product_source_id, UNHEX('e88081e4babae5aeb6204450313030') AS node_name, 678 AS template_id, 'pjt_769aa760cf3ad4d8462b7f9bd2b5e083' AS template_key
