SELECT 44903 AS model_id, '233134' AS product_source_id, UNHEX('e9a39ee582b2205131204d61726b204949') AS node_name, 678 AS template_id, 'pjt_769aa760cf3ad4d8462b7f9bd2b5e083' AS template_key
