SELECT 45895 AS model_id, '65148' AS product_source_id, UNHEX('e4baace4b89ce4baace980a0204361707475726532') AS node_name, 2662 AS template_id, 'pjt_ab1c9d680d1f14adfc826f08c509eb94' AS template_key
