SELECT 46359 AS model_id, '319297' AS product_source_id, UNHEX('e699bae4ba9120534d4f4f544820355320e58d95e69cba') AS node_name, 1051 AS template_id, 'pjt_d073637e30942bbaeeae4654471fd39b' AS template_key
