SELECT 59352 AS model_id, '325052' AS product_source_id, UNHEX('e7a59ee7899b20695432322053') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
) verified
JOIN saas_recycle_device_model_dict m
  ON m.id=verified.model_id AND m.site_id=0 AND m.node_type='model'
 AND m.source='recycle_spider' AND m.status=1
 AND BINARY m.product_source_id=BINARY verified.product_source_id
 AND BINARY m.node_name=verified.node_name
JOIN saas_recycle_check_template t
  ON t.id=verified.template_id AND t.site_id=0 AND t.status=1
 AND BINARY t.template_key=BINARY verified.template_key
LEFT JOIN saas_recycle_template_binding existing
  ON existing.site_id=0 AND existing.target_type='model_dict'
 AND existing.target_id=m.id AND existing.scene_key='manual_device_label'
WHERE existing.id IS NULL
 AND (EXISTS (SELECT 1 FROM saas_recycle_check_field f
              WHERE f.site_id=0 AND f.template_id=t.id)
      OR CASE WHEN JSON_VALID(t.schema_json)
         THEN COALESCE(JSON_LENGTH(JSON_EXTRACT(t.schema_json,'$.groups[*].fields[*]')),0)
         ELSE 0 END > 0);

-- 已核对清单 16801 至 16804
INSERT INTO saas_recycle_template_binding
  (site_id,target_type,target_id,scene_key,check_template_id,print_template_id,
   inherit_enabled,status,sort,remark,create_at,update_at)
SELECT 0,'model_dict',m.id,'manual_device_label',t.id,0,
       1,1,0,'repair_public_verified_20261004',UNIX_TIMESTAMP(),UNIX_TIMESTAMP()
FROM (
SELECT 59353 AS model_id, '322954' AS product_source_id, UNHEX('e7a59ee7899b204d462d5237362028e9809ae794a8e6acbe29') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
UNION ALL
SELECT 59354 AS model_id, '323821' AS product_source_id, UNHEX('e7a59ee7899b20563130302d4f') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
UNION ALL
SELECT 59355 AS model_id, '326615' AS product_source_id, UNHEX('e7a59ee7899b2044503830304949') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
UNION ALL
SELECT 59356 AS model_id, '322392' AS product_source_id, UNHEX('e7a59ee7899b20534b333030204949') AS node_name, 624 AS template_id, 'pjt_eb0dbf04c4ec946a06e4c491063571c6' AS template_key
) verified
JOIN saas_recycle_device_model_dict m
  ON m.id=verified.model_id AND m.site_id=0 AND m.node_type='model'
 AND m.source='recycle_spider' AND m.status=1
 AND BINARY m.product_source_id=BINARY verified.product_source_id
 AND BINARY m.node_name=verified.node_name
JOIN saas_recycle_check_template t
  ON t.id=verified.template_id AND t.site_id=0 AND t.status=1
 AND BINARY t.template_key=BINARY verified.template_key
LEFT JOIN saas_recycle_template_binding existing
  ON existing.site_id=0 AND existing.target_type='model_dict'
 AND existing.target_id=m.id AND existing.scene_key='manual_device_label'
WHERE existing.id IS NULL
 AND (EXISTS (SELECT 1 FROM saas_recycle_check_field f
              WHERE f.site_id=0 AND f.template_id=t.id)
      OR CASE WHEN JSON_VALID(t.schema_json)
         THEN COALESCE(JSON_LENGTH(JSON_EXTRACT(t.schema_json,'$.groups[*].fields[*]')),0)
         ELSE 0 END > 0);

COMMIT;

-- 本批已补数量。若与 16804 不同，先核对，不能据此覆盖已有绑定。
SELECT COUNT(*) AS verified_restored FROM saas_recycle_template_binding
WHERE site_id=0 AND remark='repair_public_verified_20261004';

-- 基准快照：42483 个型号、24484 个已有有效关联；本批预计补 16804 个。
-- 若无并发变化，执行后应为 41288 个已关联、1195 个待核对。
SELECT COUNT(*) AS total_models,
 SUM(t.id IS NOT NULL) AS valid_bound_models,
 SUM(t.id IS NULL) AS unresolved_models
FROM saas_recycle_device_model_dict m
LEFT JOIN saas_recycle_template_binding b
 ON b.site_id=0 AND b.target_type='model_dict' AND b.target_id=m.id
AND b.scene_key='manual_device_label' AND b.status=1
LEFT JOIN saas_recycle_check_template t
 ON t.id=b.check_template_id AND t.site_id=0 AND t.status=1
WHERE m.site_id=0 AND m.node_type='model' AND m.status=1;
